SELECT id, store_id, product_id, units, revenue, LAST_VALUE(units, TRUE) OVER w_hist AS last_known_units, SUM(revenue) OVER (PARTITION BY product_id, store_id ORDER BY sale_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_revenue, PERCENT_RANK() OVER (PARTITION BY product_id ORDER BY units DESC) AS units_percent_rank, ROUND(revenue / SUM(revenue) OVER (PARTITION BY product_id), 4) AS revenue_share, AVG(revenue) OVER (PARTITION BY store_id ORDER BY units, id ROWS BETWEEN 6 PRECEDING AND 1 PRECEDING) AS revenue_avg_6_prior FROM store_sales WINDOW w_hist AS (PARTITION BY product_id ORDER BY sale_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)
